/**
 * @description Tests for IntegrationHubCleanupStatus: status before and after scheduling, the saved last-run result,
 * and that only admins may use it.
 */
@IsTest
private class IntegrationHubCleanupStatusTest {

    @TestSetup
    static void setup() {
        IntegrationHubTestData.setupAll();
    }

    @IsTest
    static void schedulesWhenMissingAndShowsTheLastRun() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            Datetime finished = System.now();
            IntegrationHubMaintenance.saveResult(3, 2, finished);
            Test.startTest();
            IntegrationHubCleanupStatus.Status before = IntegrationHubCleanupStatus.getStatus();
            IntegrationHubCleanupStatus.Status after = IntegrationHubCleanupStatus.scheduleCleanup();
            IntegrationHubCleanupStatus.Status again = IntegrationHubCleanupStatus.scheduleCleanup();
            Test.stopTest();
            Assert.isTrue(after.scheduled, 'the job is scheduled');
            Assert.isNotNull(after.nextRun, 'the next run is known');
            Assert.isNotNull(after.scheduledBy, 'the user it runs as is known');
            Assert.isTrue(again.scheduled, 'scheduling twice keeps one job');
            Assert.areEqual(finished, before.lastFinished, 'the last run time is shown');
            Assert.areEqual(3, before.lastDeleted, 'the deleted count is shown');
            Assert.areEqual(2, before.lastTimedOut, 'the timed-out count is shown');
        }
    }

    @IsTest
    static void wholeNumbers() {
        System.runAs(IntegrationHubTestData.admin()) {
            Assert.isNull(IntegrationHubCleanupStatus.whole(null), 'no value stays empty');
            Assert.areEqual(4, IntegrationHubCleanupStatus.whole(4.0), 'a number becomes whole');
        }
    }

    @IsTest
    static void onlyAdmins() {
        System.runAs(IntegrationHubTestData.reader()) {
            Boolean refused = false;
            try {
                IntegrationHubCleanupStatus.getStatus();
            } catch (AuraHandledException e) {
                refused = true;
            }
            Assert.isTrue(refused, 'a reader cannot see the clean-up status');
        }
    }
}
